// WRONG (pending): drops every unanswered operation, as if it never took effect. Generated by mk_wrongs.py.
// Reference: linearizability checker for KV histories (task 168, variant b).
// Per-key Wing-Gong-Lowe search, memoised on (linearized-set, value).
package main

import (
	"bufio"
	"io"
	"math"
	"math/bits"
	"os"
	"sort"
	"strconv"
	"strings"
)

const (
	GET = iota
	PUT
	DEL
	CAS
)

const INF = math.MaxInt64

type Op struct {
	call, ret int64
	kind, key int
	a, b, res int64 // res: GET value (0 = NIL) / CAS 1=OK 0=FAIL
}

func checkKey(in []Op) bool {
	var done, pend []Op
	for _, o := range in {
		if o.ret == INF {
			pend = append(pend, o)
		} else {
			done = append(done, o)
		}
	}
	m := len(done)
	if m == 0 {
		return true
	}
	sort.SliceStable(done, func(i, j int) bool { return done[i].ret < done[j].ret })
	ops := append(done, pend...)
	n := len(ops)
	byCall := make([]int, n)
	for i := range byCall {
		byCall[i] = i
	}
	sort.SliceStable(byCall, func(i, j int) bool { return ops[byCall[i]].call < ops[byCall[j]].call })
	W := (n + 63) / 64
	key := func(s []uint64) string {
		var sb strings.Builder
		for _, w := range s {
			sb.WriteString(strconv.FormatUint(w, 36))
			sb.WriteByte(',')
		}
		return sb.String()
	}
	seen := map[string]bool{}
	start := make([]uint64, W+1)
	seen[key(start)] = true
	stack := [][]uint64{start}
	for len(stack) > 0 {
		cur := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		low := n
		for w := 0; w < W; w++ {
			if z := ^cur[w]; z != 0 {
				low = w*64 + bits.TrailingZeros64(z)
				break
			}
		}
		if low >= m {
			return true
		}
		minret := ops[low].ret
		val := int64(cur[W])
		for _, i := range byCall {
			if ops[i].call > minret {
				break
			}
			if cur[i/64]>>(uint(i)%64)&1 == 1 {
				continue
			}
			o := ops[i]
			var nv int64
			switch o.kind {
			case GET:
				if o.res != val {
					continue
				}
				nv = val
			case PUT:
				nv = o.a
			case DEL:
				nv = 0
			default:
				hit := val != 0 && val == o.a
				if i >= m {
					if hit {
						nv = o.b
					} else {
						nv = val
					}
				} else if o.res == 1 {
					if !hit {
						continue
					}
					nv = o.b
				} else {
					if hit {
						continue
					}
					nv = val
				}
			}
			nxt := make([]uint64, W+1)
			copy(nxt, cur)
			nxt[i/64] |= 1 << (uint(i) % 64)
			nxt[W] = uint64(nv)
			k := key(nxt)
			if !seen[k] {
				seen[k] = true
				stack = append(stack, nxt)
			}
		}
	}
	return false
}

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	toks := strings.Fields(string(data))
	p := 0
	next := func() string { p++; return toks[p-1] }
	atoi := func(s string) int64 { v, _ := strconv.ParseInt(s, 10, 64); return v }
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	T := int(atoi(next()))
	for t := 0; t < T; t++ {
		n := int(atoi(next()))
		byKey := map[int][]Op{}
		var order []int
		for i := 0; i < n; i++ {
			var o Op
			o.call = atoi(next())
			rs := next()
			pending := rs == "?"
			if pending {
				o.ret = INF
			} else {
				o.ret = atoi(rs)
			}
			switch next() {
			case "GET":
				o.kind = GET
			case "PUT":
				o.kind = PUT
			case "DEL":
				o.kind = DEL
			default:
				o.kind = CAS
			}
			o.key = int(atoi(next()))
			switch o.kind {
			case PUT:
				o.a = atoi(next())
			case CAS:
				o.a = atoi(next())
				o.b = atoi(next())
			}
			if !pending {
				if o.kind == GET {
					s := next()
					if s != "NIL" {
						o.res = atoi(s)
					}
				} else if o.kind == CAS {
					if next() == "OK" {
						o.res = 1
					}
				}
			}
			if pending {
				continue // constrains nothing
			}
			if _, ok := byKey[o.key]; !ok {
				order = append(order, o.key)
			}
			byKey[o.key] = append(byKey[o.key], o)
		}
		ok := true
		for _, k := range order {
			if !checkKey(byKey[k]) {
				ok = false
				break
			}
		}
		if ok {
			w.WriteString("LINEARIZABLE\n")
		} else {
			w.WriteString("VIOLATION\n")
		}
	}
}
